from .core import BASE, SITE, UPDATED, breadcrumb, faq, page, quick_answer, takeaways


def build():
    path='/en/labs/evaluation-failure/'
    target=SITE/'en/labs/evaluation-failure'
    target.mkdir(parents=True,exist_ok=True)
    title='Evaluation Failure Lab — Debug AI release decisions | AhaFrame'
    desc='Debug a simulated AI evaluation process by changing dataset composition, thresholds, safety vetoes, sample size, judge strategy, and cost gates while deciding whether a candidate should ship.'
    schema={
        '@context':'https://schema.org',
        '@graph':[
            {'@type':'WebPage','@id':BASE+path+'#webpage','url':BASE+path,'name':'Evaluation Failure Lab','description':desc,'inLanguage':'en','dateModified':UPDATED,'mainEntity':{'@id':BASE+path+'#learning-resource'}},
            {'@type':'LearningResource','@id':BASE+path+'#learning-resource','name':'Evaluation Failure Lab','description':desc,'url':BASE+path,'inLanguage':'en','educationalLevel':'Intermediate','learningResourceType':'Interactive simulation','timeRequired':'PT25M','isAccessibleForFree':True,'publisher':{'@id':BASE+'/#organization'}},
        ],
    }
    body=f'''<div class="container"><div class="breadcrumb"><a href="/en/">Home</a> / Production Labs / Evaluation Failure Lab</div><section class="lesson-hero"><div class="lesson-title-row"><div class="lesson-icon">✓</div><div><h1>Evaluation Failure Lab</h1><div class="badges"><span class="badge level">Production Lab Preview</span><span class="badge">Intermediate</span><span class="badge">25 min</span></div><p class="lede">Agent v2 looks better on the dashboard. Your job is not to tune the agent—it is to debug the evaluation process and decide whether the evidence is strong enough to ship.</p></div></div><div class="lesson-tools"><button type="button" class="btn small" data-share>Share</button></div></section>{quick_answer('Evaluation is a release-decision system, not a single score: representative slices, evidence strength, veto conditions, judge coverage, and production economics determine whether an apparent improvement is trustworthy.')}
    <div data-evaluation-lab><section class="card interactive"><div class="panel-title"><span>Naive release evaluation</span><span class="badge">Deterministic simulation</span></div><p class="subtle">The team improved retrieval and tool behavior in a customer-support agent. A demo-heavy evaluation says v2 wins. The hidden problem: long-horizon and safety-critical refund cases regressed.</p><div class="lab-control-grid" style="display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:18px"><div><label class="label" for="evaluation-dataset">Evaluation dataset</label><select id="evaluation-dataset" class="select" style="margin-top:8px"><option value="demo-biased">Demo-biased</option><option value="production-like">Production-like</option><option value="safety-heavy">Safety-heavy</option></select><label class="label" for="evaluation-threshold" style="display:block;margin-top:18px">Global pass threshold</label><div class="control-row"><input id="evaluation-threshold" class="slider" type="range" min="70" max="95" step="1" value="80"><output class="badge" data-evaluation-threshold-value>80</output></div><label class="label" for="evaluation-sample-size" style="display:block;margin-top:18px">Evaluation sample size</label><select id="evaluation-sample-size" class="select" style="margin-top:8px"><option value="50">50 cases</option><option value="100">100 cases</option><option value="200">200 cases</option><option value="500">500 cases</option></select></div><div><label class="label" for="evaluation-judge-mode">Judge strategy</label><select id="evaluation-judge-mode" class="select" style="margin-top:8px"><option value="deterministic">Deterministic checks</option><option value="rubric" selected>Semantic / rubric judge</option><option value="mixed">Mixed evaluation</option></select><button type="button" class="btn wide" data-evaluation-safety style="margin-top:16px">Safety veto: OFF</button><button type="button" class="btn wide" data-evaluation-cost-gate style="margin-top:10px">Cost gate: OFF</button><div class="note" style="margin-top:16px"><strong>Critical policy:</strong> the refund safety slice has a release floor of 80. The synthetic cost-per-success budget is 0.100 cost units.</div><div class="actions" style="margin-top:16px"><button type="button" class="btn primary" data-evaluation-production-preset>Apply production evaluation</button><button type="button" class="btn" data-evaluation-reset>Reset naive evaluation</button></div></div></div></section>
    <section class="card lesson-section" style="padding:20px;margin-top:18px"><div class="panel-title"><span>Release decision</span><strong class="decision-chip" data-evaluation-decision data-decision="SHIP">SHIP</strong></div><div class="metrics" style="margin-top:14px"><div class="metric">v1 aggregate<br><strong data-evaluation-v1>—</strong></div><div class="metric">v2 aggregate<br><strong data-evaluation-v2>—</strong></div><div class="metric">Aggregate delta<br><strong data-evaluation-delta>—</strong></div><div class="metric">Critical safety v2<br><strong data-evaluation-safety-score>—</strong></div><div class="metric">Regressions<br><strong data-evaluation-regressions>—</strong></div><div class="metric">Evidence width<br><strong data-evaluation-confidence>—</strong></div><div class="metric">Judge noise index<br><strong data-evaluation-judge-noise>—</strong></div><div class="metric">Eval cost index<br><strong data-evaluation-cost>—</strong></div></div><div class="note" style="margin-top:14px"><strong>Current diagnosis:</strong> <span data-evaluation-diagnosis>Calculating…</span></div></section>
    <section class="card lesson-section" style="padding:20px;margin-top:18px"><div class="panel-title"><span>Slice comparison</span><span class="badge">v1 → v2</span></div><p class="subtle">The aggregate is a weighted mixture. Change the dataset preset to see which failures the evaluation gives enough importance to influence the release decision.</p><div style="overflow-x:auto;margin-top:12px"><table class="feature-matrix eval-table"><thead><tr><th>Slice</th><th>Weight</th><th>v1</th><th>v2</th><th>Δ</th></tr></thead><tbody data-evaluation-slices></tbody></table></div></section>
    <section class="card lesson-section" style="padding:20px;margin-top:18px"><div class="panel-title">Economics and evidence</div><div class="compare-grid" style="margin-top:14px"><div class="compare-card warn"><span class="label">Cost per successful task</span><strong>v1 <span data-evaluation-cost-v1>—</span> · v2 <span data-evaluation-cost-v2>—</span></strong><p class="subtle">Synthetic cost units. The cost gate is intentionally independent from quality.</p></div><span class="flow-arrow">→</span><div class="compare-card good"><span class="label">Your evaluation policy</span><div data-evaluation-compare style="display:grid;gap:6px;margin-top:6px"><span>Waiting for changes…</span></div></div></div></section></div>
    {takeaways([('Averages can hide tail risk','A higher overall score can coexist with a release-blocking regression in a small but consequential slice.'),('Dataset composition is a product decision','Your evaluation distribution determines which failures count enough to influence the aggregate.'),('A veto is different from a weight','Some safety conditions should block a release rather than be averaged against easy wins elsewhere.'),('Evidence strength matters','A positive delta is not automatically trustworthy when the evaluation is underpowered or the judge has limited coverage.'),('Quality and economics are separate gates','A candidate can improve task quality while worsening cost per successful outcome.')])}
    <section class="card section-explainer"><span class="eyebrow">Production mental model</span><h2>Why can a better benchmark score produce a worse release decision?</h2><p>AI systems rarely fail uniformly. A candidate can improve common questions while regressing on long-horizon tasks, rare tool sequences, or safety-critical actions. When the evaluation compresses all of those cases into one average, the most important failure can disappear inside a strong headline number.</p><h3>Representative data beats convenient demos</h3><p>A demo-biased set overweights the cases the team already knows how to solve. A production-like set increases the influence of difficult and consequential cases. This lab uses fixed synthetic slice scores so the learner can isolate the evaluation design itself from model randomness.</p><h3>Thresholds and vetoes answer different questions</h3><p>A global threshold asks whether average performance is high enough. A veto asks whether a specific failure is unacceptable regardless of the average. If an AI system can perform an irreversible refund, a safety regression may deserve a hard release gate even when the rest of the system improves.</p><h3>More samples reduce uncertainty; they do not fix bad coverage</h3><p>The modeled evidence width shrinks as the sample size grows. That demonstrates why small evaluations provide weaker evidence. But collecting more examples from a biased distribution does not make the evaluation representative. Sample size and dataset design are independent engineering decisions.</p><h3>Judge strategy changes coverage, noise, and cost</h3><p>Deterministic checks are stable and cheap, but can miss semantic or process-level defects. Rubric judges can cover more nuanced quality but introduce judge noise and cost. Mixed evaluation combines complementary checks. None of these choices is universally correct; the evaluation method must match the failure modes that matter.</p><h3>What is simulated here?</h3><p>All slice scores, confidence behavior, judge noise, and cost values are synthetic educational quantities. No live LLM judge, benchmark, customer-support traffic, or repeated stochastic trial is being executed. Real release policies require representative data, validated graders and verifiers, and organization-specific risk criteria.</p><h3>Common questions</h3>{faq([('Should the highest aggregate score always ship?','No. Aggregate metrics are useful summaries, but they should not override critical regressions or evidence-quality requirements.'),('Is a larger evaluation set always better?','It improves evidence strength only if the cases are representative and the scoring method measures the behavior you care about.'),('Should every metric become a hard veto?','No. Vetoes are appropriate for selected non-negotiable conditions. Too many hard gates can make iteration impossible.'),('Why can the decision be INCONCLUSIVE?','Because engineering evidence can be insufficient. A release process should be allowed to say “we do not know yet” instead of forcing every noisy comparison into ship or block.')])}<div class="references"><strong>AhaFrame simulation note</strong> · Reviewed {UPDATED}. This Lab independently re-models evaluation concepts from public engineering references; values are synthetic and should not be used as universal production thresholds.</div></section>
    <section class="card build-card" data-evaluation-build><div><span class="eyebrow">Build challenge</span><h3>Define the minimum release gate for a refund-capable support agent.</h3><p>Choose the dataset mix, evidence strength, judge strategy, safety boundary, and economic constraint you would require before deployment. The goal is a defensible policy—not the highest possible dashboard score.</p></div><a class="btn" data-event="evaluation_build_challenge_started" href="/en/early-access/?intent=evaluation-build-challenge">Take the challenge →</a></section>
    <section class="card next-band"><div><strong>You debugged the evaluation process.</strong><div class="subtle">Next, Context Compression Lab will make the trade-off between token savings and lost evidence visible before the Content MVP capstone connects retrieval, agents, evaluation, and production constraints.</div></div><a class="btn primary" data-event="evaluation_paid_intent_click" href="/en/early-access/?intent=evaluation-production-labs">Get Production Labs →</a></section></div>'''
    scripts='<script src="/assets/evaluation-scenario.js" defer></script><script src="/assets/evaluation.js" defer></script>'
    (target/'index.html').write_text(page(title,desc,path,body,active='Lessons',schemas=[schema,breadcrumb([('AhaFrame','/en/'),('Production Labs','/en/#production-labs'),('Evaluation Failure Lab',path)])],scripts=scripts),encoding='utf-8')
